<template>
  <div class="app">
    <SideBar />

    <router-view v-slot="{ Component }" @openDialog="openDialog">
      <component :is="Component" v-if="Component" />
    </router-view>


    <LoadingOverlay v-if="isLoading" />

    <GlobalDialog v-if="dialog" v-model="dialog" :id="dialogId" :uniqueId="dialogUniqueId" :label="dialogLabel"
      @saveData="handleSave" />
  </div>
</template>

<script setup>
// 컴포넌트 or 페이지 불러오기
import SideBar from "./components/SideBar.vue";
import { ref, watch } from "vue";
import { computed } from "vue"
import { useUiStore } from "@/store/uiStore"

import LoadingOverlay from "@/components/LoadingOverlay.vue";
import GlobalDialog from "@/components/GlobalDialog.vue"; // 전역 다이얼로그 컴포넌트

const uiStore = useUiStore()
const isLoading = computed(() => uiStore.isLoading)

const dialog = ref(false);
const dialogId = ref("");
const dialogUniqueId = ref("");
const dialogLabel = ref("");


const openDialog = (id, uniqueId, label) => {
  dialogId.value = id;
  dialogUniqueId.value = uniqueId;
  dialogLabel.value = label;
  dialog.value = true;
};

const closeDialog = () => {
  console.log("🔸 다이얼로그 닫기 및 데이터 초기화");
  dialog.value = false;
  dialogId.value = "";
  dialogUniqueId.value = ""; // ✅ uniqueId 초기화
  dialogLabel.value = "";
};


watch(dialog, (val) => {
  if (!val) {
    closeDialog()  // ✅ 다이얼로그가 false(닫힘)일 때만 호출
  }
})

const handleSave = (data) => {
  console.log('데이터 저장 완료', data);
};

console.log('마지막 업데이트 : ', '2026-01-27');

</script>


