  position: fixed;
  inset: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  background: rgba(255, 255, 255, 0.6);
  backdrop-filter: blur(3px);

  z-index: 99999;
  /* 🔥 router-view보다 무조건 위 */
}

.loading-box {
  background: #ffffff;
  padding: 32px;
  border-radius: 12px;
  min-width: 320px;

  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
}
