<template>
  <div class="loading-overlay">
    <div class="loading-box">

      <h3>파일 분석 중입니다</h3>

      <ul class="steps">
        <li :class="stepClass(2)">
          ● 토폴로지 분석
        </li>

        <li :class="stepClass(3)">
          ● 좌표 검색
        </li>

        <li :class="stepClass(4)">
          ● 편익비용·탄소배출량 계산
        </li>
      </ul>

    </div>
  </div>
</template>

<script setup>
import { useProgressStore } from "@/store/progressStore"

const progressStore = useProgressStore()

const stepClass = (step) => {
  if (progressStore.currentStep > step) return "done"
  if (progressStore.currentStep === step) return "active"
  return ""
}
</script>

<style scoped>
.loading-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.35);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
}

.loading-box {
  background: #fff;
  padding: 32px;
  border-radius: 12px;
  width: 360px;
}

.steps li {
  margin-top: 12px;
  opacity: 0.4;
  transition: all 0.3s ease;
}

.steps li.active {
  opacity: 1;
  font-weight: 600;
  animation: blink 1.2s infinite ease-in-out;
}

.steps li.done {
  opacity: 1;
  color: #22c55e;
  animation: none;
}

@keyframes blink {
  0% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
  100% {
    opacity: 1;
  }
}
</style>