<template>
    <teleport to="body">
        <div v-if="visible" class="node-modal-backdrop">
            <div class="node-modal">

                <!-- HEADER -->
                <div class="modal-header">
                    <svg class="header-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"
                        stroke-linecap="round" stroke-linejoin="round">
                        <line x1="4" y1="6" x2="20" y2="6" />
                        <circle cx="9" cy="6" r="2" />
                        <line x1="4" y1="12" x2="20" y2="12" />
                        <circle cx="15" cy="12" r="2" />
                        <line x1="4" y1="18" x2="20" y2="18" />
                        <circle cx="11" cy="18" r="2" />
                    </svg>
                    <span class="title">Node Property Editor</span>
                </div>

                <!-- BODY -->
                <div class="modal-content">
                    <div class="modal-body">

                        <!-- LEFT -->
                        <div class="left-panel">
                            <TopologyTree :items="treeItems" mode="modal" :activeTopologyId="activeTopologyId"
                                @select-node="onSelectNode" />
                        </div>

                        <!-- RIGHT -->
                        <div class="right-panel">

                            <!-- INFO TOGGLE BAR -->
                            <div class="list-header" @click="toggleInfo">
                                <span class="twisty" :class="{ collapsed: !elementVisible }"></span>
                                <span class="list-title">
                                    {{ elementVisible ? "Hide info" : "Show info" }}
                                </span>
                            </div>

                            <div class="element-list" v-show="elementVisible">
                                <table v-if="selectedElements.length" class="prop-table">
                                    <thead>
                                        <tr>
                                            <th>요소명</th>
                                            <th>주소</th>
                                            <th>위도</th>
                                            <th>경도</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        <tr v-for="el in selectedElements" :key="el.id" @click="onSelectElementRow(el)"
                                            :class="{ active: activeElement?.id === el.id }">
                                            <td>{{ el.name }}</td>
                                            <td>
                                                <div class="address-cell">
                                                    <span class="address-text">
                                                        {{
                                                            addressMap.get(
                                                                `${el.raw.element.lat},${el.raw.element.lng}`
                                                            )?.address || "주소 조회 중..."
                                                        }}
                                                    </span>

                                                    <div v-if="addressMap.get(`${el.raw.element.lat},${el.raw.element.lng}`)?.warning"
                                                        class="address-warning">
                                                        ⚠ 국가보안시설 (주소 정보 제한)
                                                    </div>
                                                </div>
                                            </td>
                                            <td>{{ el.raw.element.lat ?? "-" }}</td>
                                            <td>{{ el.raw.element.lng ?? "-" }}</td>
                                        </tr>
                                    </tbody>
                                </table>

                                <div v-else class="empty-state">
                                    topology 또는 node를 선택하세요
                                </div>

                            </div>


                            <!-- INFO PANEL -->
                            <!-- INFO PANEL -->

                            <div class="info-panel-wrapper">
                                <div class="info-panel" v-if="activeRawElement">
                                    <h4 class="info-title">
                                        {{ activeRawElement.label }} 상세 정보
                                    </h4>

                                    <table class="info-table">
                                        <thead>
                                            <tr>
                                                <th>속성명</th>
                                                <th>값</th>
                                                <th>단위</th>
                                            </tr>
                                        </thead>

                                        <tbody>
                                            <template v-for="group in activeRawElement.property || []"
                                                :key="group.name">
                                                <!-- 🔹 GROUP HEADER ROW -->
                                                <tr class="group-row">
                                                    <td colspan="3">
                                                        {{ group.name || "기본속성" }}
                                                    </td>
                                                </tr>

                                                <!-- 🔹 VALUE ROWS -->
                                                <tr v-for="v in group.values || []" :key="v.name" class="value-row">
                                                    <td class="col-name">{{ v.name }}</td>

                                                    <td class="col-value">
                                                        <!-- 숫자일 때만 input -->
                                                        <input v-if="Number.isFinite(v.data)" v-model.number="v.data"
                                                            type="number" class="value-input" />
                                                        <span v-else class="value-text">
                                                            {{ v.data }}
                                                        </span>
                                                    </td>

                                                    <td class="col-unit">{{ v.unit || "-" }}</td>
                                                </tr>
                                            </template>
                                        </tbody>
                                    </table>
                                </div>

                                <!-- element 아닌 걸 클릭했을 때 -->
                                <div v-else class="info-empty">
                                    요소를 선택하면 상세 정보가 표시됩니다.
                                </div>
                            </div>
                        </div>

                    </div>

                    <!-- FOOTER -->
                    <div class="modal-footer">
                        <button class="btn-apply" @click="save">Apply</button>
                        <button class="btn-cancel" @click="$emit('close')">Close</button>
                    </div>
                </div>

            </div>
        </div>
    </teleport>
</template>



<script setup>
import { ref, watch, defineProps, defineEmits, computed } from "vue"
import TopologyTree from "./TopologyTree.vue"

defineEmits(["close", "save"])

const activeElement = ref(null)

const elementVisible = ref(true)

const toggleInfo = () => {
    elementVisible.value = !elementVisible.value
}

const onSelectElementRow = (el) => {
    activeElement.value = el
}

const activeRawElement = computed(() => {
    if (!activeElement.value) return null
    if (activeElement.value.type !== "element") return null
    return activeElement.value.raw?.element || null
})

const props = defineProps({
    visible: Boolean,
    treeItems: {
        type: Array,
        required: true
    },
    initialTopologyId: [String, Number]
})

/* 🔑 modal 단일 상태 */
const activeTopologyId = ref(null)

/* 주소 캐시 (lat,lng → { address, warning }) */
const addressMap = ref(new Map())

/* modal 열릴 때 초기 topology 설정 */
watch(
    () => props.initialTopologyId,
    (id) => {
        activeTopologyId.value = id
    },
    { immediate: true }
)

/* Tree에서 topology 선택 */
const onSelectNode = (node) => {
    if (node.type === "topology") {
        activeTopologyId.value = node.id
    }
}

/* 선택된 topology 하위 element 목록 */
const selectedElements = computed(() => {
    if (!activeTopologyId.value) return []

    const topology = props.treeItems.find(
        t => t.id === activeTopologyId.value
    )
    if (!topology?.children) return []

    // 🔥 가공하지 말고 원본 element 그대로 반환
    return topology.children.filter(
        child => child.type === "element"
    )
})

const normalizeAddress = (address) => {
    if (!address) return address
    return address.replace(/^대한민국\s*/, "")
}

/* 역지오코딩 */
const getAddressFromCoordinates = (lat, lng) => {
    return new Promise((resolve, reject) => {
        const geocoder = new window.google.maps.Geocoder()

        geocoder.geocode(
            { location: { lat, lng } },
            (results, status) => {
                if (status !== "OK" || !results?.length) {
                    reject(status)
                    return
                }

                // ❗ Plus Code 여부 확인
                const plusCodeResult = results.find(r =>
                    r.types.includes("plus_code")
                )

                const preferred = results.find(r =>
                    r.types.includes("street_address") ||
                    r.types.includes("route") ||
                    r.types.includes("premise")
                )

                const fallback = results.find(r =>
                    r.types.includes("administrative_area_level_2") ||
                    r.types.includes("administrative_area_level_1")
                )

                // ✅ Plus Code → 항상 warning
                if (plusCodeResult && !preferred) {
                    resolve({
                        address: "주소없음",
                        warning:
                            "해당 위치는 시설 부지 내부로, 도로명 주소가 존재하지 않아 좌표 기반 주소(Plus Code)가 표시됩니다."
                    })
                    return
                }

                // ✅ 정상 주소
                if (preferred) {
                    resolve({
                        address: normalizeAddress(preferred.formatted_address),
                        warning: null
                    })
                    return
                }

                // ✅ 행정구역 fallback
                resolve({
                    address: fallback?.formatted_address || results[0].formatted_address,
                    warning:
                        "해당 위치는 시설 부지 내부로, 정확한 도로명 주소가 제공되지 않을 수 있습니다."
                })
            }
        )
    })
}

/* 주소 자동 수집 */
watch(
    selectedElements,
    async (elements) => {
        for (const el of elements) {
            const lat = el.raw?.element?.lat
            const lng = el.raw?.element?.lng

            if (lat == null || lng == null) continue

            const key = `${lat},${lng}`
            if (addressMap.value.has(key)) continue

            try {
                const result = await getAddressFromCoordinates(lat, lng)
                addressMap.value.set(key, result)
            } catch {
                addressMap.value.set(key, {
                    address: "주소 변환 실패",
                    warning: "좌표 기준 주소를 확인할 수 없습니다."
                })
            }
        }
    },
    { immediate: true }
)
</script>



<style scoped>
