    color: #374151;
}

.info-table td {
    padding: 6px 10px;
    border-bottom: 1px solid #e5e7eb;
    vertical-align: middle;
}

/* 🔹 그룹 헤더 */
.group-row td {
    background: #f1f5f9;
    font-weight: 600;
    color: #1f2937;
    border-top: 1px solid #cbd5e1;
}

/* 🔹 값 row */
.value-row:hover {
    background: #f9fafb;
}

.value-row td {
    padding: 7px 10px;
    vertical-align: middle;
}

/* 컬럼 비율 재정리 */
.col-name {
    width: 30%;
    color: #374151;
}

.col-value {
    width: 35%;
    font-weight: 500;
    color: #111827;
}

.col-unit {
    width: 35%;
    color: #6b7280;
}

/* 🔼 상단 element 리스트 */
.element-list {
    flex: 0 0 40%;
    min-height: 120px;
    max-height: 45%;
    overflow-y: auto;
    margin-bottom: 10px;
    border-bottom: 1px solid #e5e7eb;
}

/* 🔽 하단 info panel */
.info-panel-wrapper {
    flex: 1;
    overflow-y: auto;
    padding-top: 8px;
}

/* info-panel 내부는 스크롤 안 줌 */
.info-panel {
    overflow: visible;
}

/* 🔹 토글 바 */
.info-toggle {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 8px;
    margin-bottom: 4px;

    font-size: 12.5px;
    color: #374151;
    cursor: pointer;
    user-select: none;

    background: #f9fafb;
    border: 1px solid #e5e7eb;
    border-radius: 4px;
}

.info-toggle:hover {
    background: #f1f5f9;
}

/* 🔹 화살표 */
.info-toggle .arrow {
    display: inline-block;
    transition: transform 0.2s ease;
    font-size: 12px;
}

.info-toggle .arrow.collapsed {
    transform: rotate(90deg);
}

/* 🔹 info panel 접힘 애니메이션 */
.element-list {
    transition: all 0.25s ease;
}

/* 🔹 리스트 상단 헤더 바 */
.list-header {
    display: flex;
    align-items: center;
    gap: 6px;

    height: 28px;
    padding: 0 10px;

    font-size: 12.5px;
    color: #1f2937;

    background: #f3f4f6;
    border: 1px solid #d1d5db;
    border-bottom: none;
    /* 🔑 테이블과 붙게 */

    cursor: pointer;
    user-select: none;
}

/* hover 시 툴 느낌 */
.list-header:hover {
    background: #e5e7eb;
}

/* 🔹 삼각형 (윈도우 툴 스타일) */
.twisty {
  width: 0;
  height: 0;
  border-top: 5px solid transparent;
  border-bottom: 5px solid transparent;
  border-left: 6px solid #374151;

  transform: rotate(-90deg);
  transition: transform 0.15s ease;
}

/* 펼쳐진 상태 */
.twisty.collapsed {
  transform: rotate(90deg);
}

/* 🔹 텍스트 */
.list-title {
    font-weight: 500;
}

.address-cell {
    display: flex;
    gap: 5px;
}

.value-input {
    width: 100%;
    height: 28px;
    padding: 4px 8px;

    font-size: 12.5px;
    font-weight: 500;
    color: #111827;

    background: #ffffff;
    border: 1px solid #d1d5db;
    border-radius: 4px;

    outline: none;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

/* hover */
.value-input:hover {
    border-color: #9ca3af;
}

/* focus */
.value-input:focus {
    border-color: #2563eb;
    box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.15);
    background: #ffffff;
}

/* number input 화살표 정리 (선택) */
.value-input::-webkit-outer-spin-button,
.value-input::-webkit-inner-spin-button {
    -webkit-appearance: none;
    margin: 0;
}
</style>