<template>
  <aside class="header">

    <!-- 왼쪽 영역 -->
    <div class="left-area">
      <div class="logo">
        <img :src="logoURL" alt="Vue" />
      </div>

      <div class="menu">
        <div v-for="step in steps" :key="step.path" class="button" :class="{
          active: isActive(step.path),
          completed: isCompleted(step.key),
        }" @click="navigateToStep(step.path, step.key)">
          <span class="material-icons">{{ step.label }}</span>
          <span class="text">{{ step.name }}</span>
        </div>
      </div>
    </div>

    <!-- 오른쪽 영역 -->
    <div class="right-area">
      <div class="datetime">
        <span class="date">{{ currentDate }}</span>
        <span class="time">{{ currentTime }}</span>
      </div>
      <span class="user">👤 {{ userId }}</span>
      <button class="logout" @click="logout">로그아웃</button>
    </div>

  </aside>

  <!-- 다이얼로그 -->
  <v-dialog v-model="showDialog" max-width="400px">
    <v-card>
      <v-card-title>알림</v-card-title>
      <v-card-text>{{ dialogText }}</v-card-text>
      <v-card-actions>
        <v-btn color="primary" @click="showDialog = false">닫기</v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script setup>
import { computed, ref, onMounted, onUnmounted } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useProgressStore } from "@/store/progressStore";
import logoURL from "../assets/mrtLogo.png";

const route = useRoute();
const router = useRouter();
const progressStore = useProgressStore();

const currentDate = ref("");
const currentTime = ref("");
const userId = ref("admin"); // 나중에 auth store에서 가져오면 됨
let timer = null;


var dialogText = ref("");
const showDialog = ref(false);


const updateTime = () => {
  const now = new Date();

  currentDate.value = now.toLocaleDateString();   // 날짜
  currentTime.value = now.toLocaleTimeString();   // 시간
};


onMounted(() => {
  updateTime();
  timer = setInterval(updateTime, 1000);
});

onUnmounted(() => {
  clearInterval(timer);
});


const steps = [
  { path: "/step1", name: "송배전망 배치", label: "STEP1", key: "step1" },
  { path: "/step3", name: "좌표설정", label: "STEP2", key: "step3" },
  { path: "/step4", name: "결과출력", label: "STEP3", key: "step4" },
];

//  현재 Step인지 확인
const isActive = (path) => route.path === path;

//  완료된 Step인지 확인 (computed 사용)
const isCompleted = (stepKey) =>
  computed(() => progressStore.isStepCompleted(stepKey)).value;

//  Step 클릭 시 이동 (완료된 Step만 이동 가능)
const navigateToStep = (path, stepKey) => {
  if (progressStore.isStepCompleted(stepKey) || path === "/step1") {
    router.push(path);
  } else {
    dialogText = "이전 Step을 완료해야 이동할 수 있습니다.";
    showDialog.value = true;
  }
};
</script>

<style lang="scss" scoped>
.header {
  display: flex;
  align-items: center;
  justify-content: space-be;
  height: var(--header-size);
  padding: 0 32px;
  background-color: var(--background-light);
  border-bottom: 2px solid var(--primary-color);
}

.left-area {
  display: flex;
  align-items: center;
  gap: 40px;
}

.menu {
  display: flex;
  gap: 32px;
}

.right-area {
  display: flex;
  align-items: center;
  gap: 20px;
  font-size: 0.9rem;
}

.datetime {
  display: flex;
  flex-direction: column;   // 🔑 위아래 배치
  align-items: flex-end;    // 오른쪽 정렬
  line-height: 1.2;
}

.date {
  font-size: 0.8rem;
  color: var(--text-sub);
}

.time {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-dark);
}

.user {
  font-weight: 600;
}

.logout {
  padding: 6px 14px;
  border-radius: 6px;
  border: none;
  background: var(--primary-color);
  color: white;
  cursor: pointer;

  &:hover {
    opacity: 0.85;
  }
}

aside {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--background-light);
  color: var(--text-dark);
  height: var(--header-size);
  padding: 0 10%;
  box-shadow: 0px 2px 10px rgba(0, 0, 0, 0.1);
  transition: all 0.3s ease-in-out;
  border-bottom: 2px solid var(--primary-color);

  .logo {
    display: flex;
    align-items: center;

    img {
      margin-left: 40px;
      width: 120px;
      height: auto;
    }
  }

  .menu {
    display: flex;
    gap: 50px;
    margin-left: auto;
    margin-right: auto;
    height: 80%;

    .button {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      text-decoration: none;
      padding: 12px 20px;
      border-radius: 8px;
      font-size: 1rem;
      font-weight: bold;
      position: relative;
      background: none;
      cursor: not-allowed; // 기본적으로 클릭 방지
      transition: all 0.3s ease-in-out;
      border: 2px solid transparent;

      .material-icons {
        font-size: 0.8rem;
        transition: all 0.3s ease;
        color: var(--primary-color);
      }

      /*  현재 Step 강조 */
      &.active {
        color: #063480;
        font-weight: bold;
        font-size: 20px;
        cursor: default;

        &::after {
          content: "";
          position: absolute;
          bottom: -4px;
          left: 50%;
          width: 50%;
          height: 3px;
          background: #063480;
          transform: translateX(-50%);
          border-radius: 2px;
          transition: width 0.3s ease-in-out;
        }

        .material-icons {
          color: #063480;
        }
      }

      /*  완료된 Step 강조 (클릭 가능) */
      &.completed {
        color: #063480;
        font-weight: bold;
        font-size: 20px;
        cursor: pointer;

        .material-icons {
          color: #063480;
        }

        &:hover {
          transform: scale(1.08);
        }
      }
    }
  }
}
</style>