<template>
  <div class="result-page">
    <div class="content-container">


      <!-- 🔹 좌측 트리 -->
      <div class="left-panel">

        <v-card>
          <v-card-title>
            <span> 송배전망</span>


          </v-card-title>

          <v-card-text>

            <TopologyTree mode="result" :items="treeItems" :resultCheckedMap="resultCheckedMap"
              :resultIndeterminateMap="resultIndeterminateMap" @toggle-result-node="onToggleResultNode" />
          </v-card-text>
        </v-card>


        <v-card>
          <v-card-title>
            <span>Topologys</span>
          </v-card-title>

          <v-card-text>
            <TopologyTree mode="result" :items="treeItems_topology" :resultCheckedMap="resultCheckedMap"
              :resultIndeterminateMap="resultIndeterminateMap" @toggle-result-node="onToggleResultNode" />

          </v-card-text>
        </v-card>




      </div>

      <!-- 🔹 우측 차트 -->
      <div class="right-scroll-wrapper">
        <div class="right-panel">
          <v-card class="graph-card" outlined>
            <div class="chart-section">
              <div class="chart-title">
                구축 및 편익비용
              </div>

              <!-- 🔹 2 x 3 Grid -->
              <div class="chart-grid">
                <div v-for="(topology, idx) in topologyList" :key="idx" class="chart-wrapper">
                  <!-- ✅ Topology 타이틀 -->
                  <div class="topology-title">
                    Topology {{ idx + 1 }}
                  </div>

                  <div class="chartZone">



                    <div class="barChart-Area">
                      <canvas ref="barCharts" height="220"></canvas>
                    </div>

                    <div class="doughtnutChart-Area">
                      <canvas ref="doughnutCharts" height="220"></canvas>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </v-card>

          <!-- <v-card class="graph-card">

            <div class="chart-section">
              <div class="chart-title">
                연간 탄소배출량
              </div>

              <div class="chart-wrapper">
                 <canvas ref="carbonBarChart" height="450"></canvas>

              </div>
            </div>


          </v-card> -->

          <!-- 하단 버튼 -->

          <div class="footer-bar">
            <v-btn color="primary" class="report-btn" @click="exportAllToPDF">
              보고서 생성
            </v-btn>
          </div>
        </div>
      </div>



    </div>
  </div>
</template>


<script setup>
import { ref, computed, onMounted, nextTick, watch } from "vue"
import Chart from "chart.js/auto"
import ChartDataLabels from "chartjs-plugin-datalabels"
import { useTopologyStore } from "@/store/topologyStore"
import { storeToRefs } from "pinia"
import TopologyTree from "@/components/TopologyTree.vue"

Chart.register(ChartDataLabels)

// ==============================
// Store
// ==============================
const topologyStore = useTopologyStore()
const { topologyList } = storeToRefs(topologyStore)

// ==============================
// Chart refs
// ==============================
const barCharts = ref([])
const doughnutCharts = ref([])

const carbonBarChart = ref(null)
const carbonDoughnutChart = ref(null);



let barChartInstances = []
let doughnutChartInstances = []


let carbonBarChartInstance = null
let carbonDoughnutChartInstance = null

const tableItems = ref([])
const checkedMap = ref([])

// ==============================
// Tree filter state (기존 유지)
// ==============================
const resultCheckedMap = ref({})
const resultIndeterminateMap = ref({})



const treeItems = computed(() => [
  {
    name: "송배전망",
    type: "group",
    children: [
      { name: "765kV", type: "node", children: [] },
      { name: "345kV", type: "node", children: [] },
      { name: "154kV", type: "node", children: [] },
      { name: "22.9kV", type: "node", children: [] }
    ]
  },
  {
    name: "NWAs",
    type: "group",
    children: [
      { name: "태양광", type: "node", children: [] },
      { name: "풍력", type: "node", children: [] },
      { name: "해상풍력", type: "node", children: [] },
      { name: "ESS", type: "node", children: [] },
      { name: "EV", type: "node", children: [] },
      { name: "EVC", type: "node", children: [] },
      { name: "DR", type: "node", children: [] },
      { name: "VPP", type: "node", children: [] }
    ]
  }
])


const treeItems_topology = computed(() => {
  if (!Array.isArray(topologyList.value)) return []

  return [
    {
      name: "Topologys",
      type: "group",
      children: topologyList.value.map((_, index) => ({
        name: `Topology ${index + 1}`,
        type: "topology",
        topologyIndex: index,
        children: []
      }))
    }
  ]
})


const initResultCheckedMap = (tree) => {
  const map = {}

  const walk = (node) => {
    map[node.name] = true        // 🔥 기본값: 전부 체크
    node.children?.forEach(walk)
  }

  tree.forEach(walk)
  return map
}

onMounted(() => {
  const mergedTree = [
    ...treeItems.value,
    ...treeItems_topology.value
  ]

  checkedMap.value = initResultCheckedMap(mergedTree)
  const indeterminateMap = initResultCheckedMap(mergedTree)

  // 🔥 전부 true로
  Object.keys(checkedMap.value).forEach(key => {
    console.log(key)

    if (key === "345kV"){
      checkedMap.value[key] = false
    }else{
      checkedMap.value[key] = true
    }
    indeterminateMap[key] = false
  })

  resultCheckedMap.value = checkedMap.value
  resultIndeterminateMap.value = indeterminateMap
})

const updateParentState = (node) => {
  if (!node.children?.length) return

  const children = node.children
  const checkedCount = children.filter(
    c => resultCheckedMap.value[c.name] === true
  ).length

  if (checkedCount === children.length) {
    resultCheckedMap.value[node.name] = true
    resultIndeterminateMap.value[node.name] = false
  }
  else if (checkedCount === 0) {
    resultCheckedMap.value[node.name] = false
    resultIndeterminateMap.value[node.name] = false
  }
  else {
    resultCheckedMap.value[node.name] = false
    resultIndeterminateMap.value[node.name] = true
  }
}

const toggleWithChildren = (node, checked) => {
  resultCheckedMap.value[node.name] = checked
  resultIndeterminateMap.value[node.name] = false

  node.children?.forEach(child =>
    toggleWithChildren(child, checked)
  )
}


const onToggleResultNode = ({ name, checked }) => {

  // 🔹 1. grid / nwas tree
  let node = findNodeByName(treeItems.value, name)

  // 🔹 2. topology tree
  if (!node) {
    node = findNodeByName(treeItems_topology.value, name)
  }
  if (!node) return

  // 1️⃣ 자신 + 하위 cascade
  toggleWithChildren(node, checked)

  // 2️⃣ 부모 상태 재계산 (양쪽 트리 모두)
  let parent =
    findParentByName(treeItems.value, name) ??
    findParentByName(treeItems_topology.value, name)

  while (parent) {
    updateParentState(parent)
    parent =
      findParentByName(treeItems.value, parent.name) ??
      findParentByName(treeItems_topology.value, parent.name)
  }
}

const findNodeByName = (nodes, targetName) => {
  for (const node of nodes) {
    if (node.name === targetName) return node
    if (node.children?.length) {
      const found = findNodeByName(node.children, targetName)
      if (found) return found
    }
  }
  return null
}

const findParentByName = (nodes, targetName, parent = null) => {
  for (const node of nodes) {
    if (node.name === targetName) return parent
    if (node.children?.length) {
      const found = findParentByName(node.children, targetName, node)
      if (found) return found
    }
  }
  return null
}

// ==============================
// Tree 기반 선택된 Topology
// ==============================
const selectedTopologyIndexes = computed(() =>
  Object.entries(resultCheckedMap.value)
    .filter(([key, checked]) =>
      checked && key.startsWith("Topology ")
    )
    .map(([key]) =>
      Number(key.replace("Topology ", "")) - 1
    )
)



// ==============================
// Topology → Map 변환 (기존 유지)
// ==============================
const arrayToMap = (list) =>
  list.map(route => {
    if (!Array.isArray(route)) return new Map()
    return new Map(
      route
        .filter(n => n && typeof n === "object")
        .map(n => [
          n.label?.replace(/-[A-Z]$/i, "") || "",
          { ...n }
        ])
    )
  })

const map_topologyList = computed(() => arrayToMap(topologyList.value))


// ==============================
// 🌱 탄소 계산 (요약)
// ==============================
const CARBON_FACTOR = {
  석탄화력: 820, 원전: 12, 소수력: 24, 가스복합: 490,
  태양광: 48, 풍력: 11, 해상풍력: 12,
  ESS: 48, EV: 490, EVC: 490, DR: 490, VPP: 490
}


// ==============================
// 📏 거리 계산 함수 (절대 유지)
// ==============================
const getDistance = (lat1, lng1, lat2, lng2) => {
  const R = 6371e3; // m
  const rad = Math.PI / 180;
  const phi1 = lat1 * rad;
  const phi2 = lat2 * rad;
  const dPhi = (lat2 - lat1) * rad;
  const dLambda = (lng2 - lng1) * rad;

  const a =
    Math.sin(dPhi / 2) ** 2 +
    Math.cos(phi1) * Math.cos(phi2) * Math.sin(dLambda / 2) ** 2;
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return (R * c) / 1000; // km
};



const calcCostData = (group, nwasNodes) => {

  /* ===============================
   * 공통 유틸
   * =============================== */
  const safeNum = (v) => {
    const n = Number(v)
    return isNaN(n) || !isFinite(n) ? 0 : n
  }

  /* ===============================
   * 1️⃣ 노드 추출 (항상 전체)
   * =============================== */
  const demand =
    group.get("수요지역") ||
    group.get("수요지역-A") ||
    group.get("수요지역-B")

  const k765 = group.get("765kV") || group.get("765kV-A")
  const k345 = group.get("345kV") || group.get("345kV-A")
  const k154 = group.get("154kV") || group.get("154kV-A")
  const k229 = group.get("22.9kV") || group.get("22.9kV-A")


  /* ===============================
   * 2️⃣ 거리 계산 (항상 유효)
   * =============================== */

  // ===============================
  // 2. 거리 계산 (항상 유지)
  // ===============================
  const dist765 = (k765 && k345)
    ? getDistance(k765.lat, k765.lng, k345.lat, k345.lng)
    : 0

  const dist345 = (k345 && k154)
    ? getDistance(k345.lat, k345.lng, k154.lat, k154.lng)
    : 0

  const dist154 = (k154 && k229)
    ? getDistance(k154.lat, k154.lng, k229.lat, k229.lng)
    : 0

  const dist229 = (k229 && demand)
    ? getDistance(k229.lat, k229.lng, demand.lat, demand.lng)
    : 0

  const transmissionDistance =
    dist765 + dist345 + dist154

  /* ===============================
 * 3️⃣ 송전망 비용 계산 (항상 계산)
 * =============================== */
  const calcTransmissionCost = (node) => {
    if (!node || !demand) return 0

    const prop = node.property || []

    const connect =
      prop.find(p => p.name.includes("송전접속단가"))?.values || []

    const loss =
      prop.find(p => p.name.includes("송전손실단가"))?.values || []

    const findVal = (arr, key) =>
      safeNum(arr.find(v =>
        v.name.replace(/\s/g, "").includes(key)
      )?.data)

    const baseUnit = findVal(connect, "기본") || 667.61
    const useUnit = findVal(connect, "사용") || 1.42
    const lossUnit = findVal(loss, "석탄화력") || 0.03

    const demandMW =
      safeNum(
        demand.property?.[0]?.values
          ?.find(v => v.name.includes("수요"))?.data
      )

    const demandKW = demandMW * 1000
    const dailyHr = 8

    const buildUnit =
      safeNum(
        node.property?.[0]?.values
          ?.find(v => v.name.includes("건설단가"))?.data
      )

    const construction =
      buildUnit > 0
        ? buildUnit * 1000000 * transmissionDistance
        : 0

    const connection =
      demandKW * useUnit * dailyHr * 365 +
      demandKW * baseUnit

    const lossCost =
      demandKW * (lossUnit / 1000) * dailyHr * 365

    return construction + connection + lossCost
  }

  const cost765 = calcTransmissionCost(k765)
  const cost345 = calcTransmissionCost(k345)
  const cost154 = calcTransmissionCost(k154)

  // ===============================
  // 4. 배전망 22.9kV 비용
  // ===============================
  let cost229 = 0

  if (k229 && demand) {
    const prop =
      k229.property?.find(p =>
        p.name.includes("배전망구축단가")
      )?.values || []

    const expansionType = k229.expansionType || "신축"
    const powerType = k229.powerType || "AC"
    const groupKey = `${expansionType}-${powerType}`

    const unit =
      prop.filter(v => v.group === groupKey)
        .reduce((s, v) => s + safeNum(v.data), 0)

    cost229 = dist229 * unit * 10000
  }


  // ------------------------------
  // ⚙️ NWAs 계산
  // ------------------------------
  const calcNWAsCost = (nodes) => {
    const total = {}

    const safeNum = (v) => {
      const n = Number(v)
      return isNaN(n) ? 0 : n
    }

    // 설치용량(MW)
    const getCapacityMW = (node) => {
      const baseProp = node.property?.find(p =>
        Array.isArray(p.values) &&
        p.values.some(v => v.name === "설치용량")
      )

      return safeNum(
        baseProp?.values?.find(v => v.name === "설치용량")?.data
      )
    }

    // 구축단가 property
    const getCostProp = (node) =>
      node.property?.find(p => p.name?.includes("구축단가"))

    // 연계비 구간 선택
    const pickGridCost = (values, capacityMW) => {
      if (capacityMW <= 1) {
        return values.find(v => v.name.includes("1MW이하"))
      }
      if (capacityMW <= 50) {
        return values.find(v => v.name.includes("1MW~50MW"))
      }
      return values.find(v => v.name.includes("50MW이상"))
    }

    nodes.forEach(node => {
      const label = node.key?.replace(/-A|-B/g, "") || "NWAs"
      const expansionType = node.expansionType || "신축"

      const capacityMW = getCapacityMW(node)
      const capacityKW = capacityMW * 1000

      const costProp = getCostProp(node)
      const values = costProp?.values || []
      const buildValues = values.filter(v => v.group === expansionType)

      let cost = 0

      switch (label) {

        // ==================================================
        // ESS / 태양광 / 풍력
        // 수식:
        // (건설·설비비 + 유지비 + 인허가비) × 용량
        // + 연계비(조건부)
        // ==================================================
        case "ESS":
        case "태양광":
        case "풍력": {
          let unitCostKW = 0       // 거래단가
          let connectCost = 0      // 연계비
          let fixedCost = 0        // 고정비

          // 1️⃣ 거래단가(kW)
          buildValues.forEach(v => {
            if (
              v.name.includes("설비비용") ||
              v.name.includes("건설비용") ||
              v.name.includes("유지비용") ||
              v.name.includes("인허가비용")
            ) {
              unitCostKW += safeNum(v.data)
            }
          })

          // 2️⃣ 연계비 (부과 기준 충족 시)
          // 태양광/풍력/ESS: 10MW 이상
          if (capacityMW >= 10) {
            const grid = pickGridCost(buildValues, capacityMW)
            if (grid?.data) {
              connectCost += safeNum(grid.data) * 1000 * capacityKW
            }
          }

          // 3️⃣ 고정비
          const fixed = buildValues.find(v =>
            v.unit?.includes("억원/고정비")
          )
          if (fixed?.data) {
            fixedCost += safeNum(fixed.data) * 100000000
          }

          cost =
            unitCostKW * 1000 * capacityKW
            + connectCost
            + fixedCost

          break
        }

        // ==================================================
        // 해상풍력
        // 연계비 필수(대규모)
        // ==================================================
        case "해상풍력": {
          let unitCostKW = 0
          let fixedCost = 0

          buildValues.forEach(v => {
            if (v.unit?.includes("천원/kW")) {
              unitCostKW += safeNum(v.data)
            }
            if (v.unit?.includes("억원/고정비")) {
              fixedCost += safeNum(v.data) * 100000000
            }
          })

          cost = unitCostKW * 1000 * capacityKW + fixedCost
          break
        }

        // ==================================================
        // EV
        // 연계비 없음
        // ==================================================
        case "EV": {
          let unitCostKW = 0

          buildValues.forEach(v => {
            if (
              v.name.includes("차량") ||
              v.name.includes("유지")
            ) {
              unitCostKW += safeNum(v.data)
            }
          })

          cost = unitCostKW * 1000 * capacityKW
          break
        }

        // ==================================================
        // EVC
        // 연계비 기준: 300kW 이상
        // ==================================================
        case "EVC": {
          let unitCostKW = 0
          let connectCost = 0

          buildValues.forEach(v => {
            if (v.unit?.includes("천원/kW")) {
              unitCostKW += safeNum(v.data)
            }
          })

          if (capacityKW >= 300) {
            const grid = pickGridCost(buildValues, capacityMW)
            if (grid?.data) {
              connectCost += safeNum(grid.data) * 1000 * capacityKW
            }
          }

          cost = unitCostKW * 1000 * capacityKW + connectCost
          break
        }

        // ==================================================
        // DR / VPP
        // 통신 연계비 필수
        // ==================================================
        case "DR":
        case "VPP": {
          let unitCostKW = 0
          let commCost = 0

          buildValues.forEach(v => {
            if (
              v.name.includes("구축비") ||
              v.name.includes("유지비용")
            ) {
              unitCostKW += safeNum(v.data)
            }
            if (v.name.includes("통신")) {
              commCost += safeNum(v.data) * 1000 * capacityKW
            }
          })

          cost = unitCostKW * 1000 * capacityKW + commCost
          break
        }

        default:
          cost = 0


      }

      total[label] = Math.max(0, cost)
    })


    return total
  }


  const nwasCosts = calcNWAsCost(nwasNodes);


  // ===============================
  // 6. Tree 기준 비용 집계
  // ===============================

  const transSum =
    (checkedMap.value["765kV"] ? cost765 : 0) +
    (checkedMap.value["345kV"] ? cost345 : 0) +
    (checkedMap.value["154kV"] ? cost154 : 0) +
    (checkedMap.value["22.9kV"] ? cost229 : 0)

  const nwasSum =
    Object.entries(nwasCosts)
      .reduce((sum, [label, cost]) =>
        sum + (checkedMap.value[label] ? safeNum(cost) : 0), 0)



  // ===============================
  // 7. 편익 계산 (정의 고정)
  // ===============================
  const benefit = safeNum(transSum - nwasSum)


  // ✅ 편익 및 총합 (NaN 방지)


  // ------------------------------
  // 📊 Chart.js 데이터 구성
  // ------------------------------
  const bar = {
    labels: ["배전망", "NWAs", "편익"],
    datasets: [
      {
        label: "765kV",
        data: [checkedMap.value["765kV"] ? cost765 : 0, 0, 0],
        backgroundColor: "#6366F1",
      },
      {
        label: "345kV",
        data: [checkedMap.value["345kV"] ? cost345 : null, null, null],
        backgroundColor: "#60A5FA",
      },
      {
        label: "154kV",
        data: [checkedMap.value["154kV"] ? cost154 : null, null, null],
        backgroundColor: "#FBBF24",
      },
      {
        label: "22.9kV",
        data: [checkedMap.value["22.9kV"] ? cost229 : null, null, null],
        backgroundColor: "#34D399",
      },
      ...Object.entries(nwasCosts).map(([key, val], idx) => ({
        label: key,
        data: [null, checkedMap.value[key] ? val : null, null],
        backgroundColor: [
          "#E879F9",
          "#10B981",
          "#F87171",
          "#3B82F6",
          "#F59E0B",
          "#6366F1",
          "#22C55E",
          "#0EA5E9",
        ][idx],
      })),
      { label: "B/C", data: [null, null, benefit], backgroundColor: "#FDBA74" },
    ],
  };


  const doughnut = {
    labels: ["765kV", "345kV", "154kV", "22.9kV"],
    datasets: [
      {

        // data: [cost229],
        data: [cost765, cost345, cost154, cost229],
        backgroundColor: ["#6366F1", "#60A5FA", "#FBBF24", "#34D399"],
      },
    ],
  };

  // ------------------------------
  // 🧾 표 데이터 구성 (category 키 통일)
  // ------------------------------
  const nwasLabels = [
    "태양광",
    "풍력",
    "해상풍력",
    "ESS",
    "EV",
    "EVC",
    "DR",
    "VPP",
  ];

  // const fmt = (num) => {
  //   const safe = safeNum(num);
  //   if (safe === 0) return "-"; // 🔸 0이면 하이픈 표시
  //   return Math.round(safe).toLocaleString("ko-KR", {
  //     maximumFractionDigits: 0,
  //   });
  // };


  const table = [
    {
      category: "765kV",
      value: checkedMap.value["765kV"] ? cost765 : 0
    },
    {
      category: "345kV",
      value: checkedMap.value["345kV"] ? cost345 : 0
    },
    {
      category: "154kV",
      value: checkedMap.value["154kV"] ? cost154 : 0
    },
    {
      category: "22.9kV",
      value: checkedMap.value["22.9kV"] ? cost229 : 0
    },
    { category: "배전망 합계", value: transSum },

    ...nwasLabels.map(k => ({
      category: k,
      value: checkedMap.value[k]
        ? safeNum(nwasCosts[k]) || 0
        : 0
    })),


    { category: "NWAs 합계", value: nwasSum },
    { category: "편익비용", value: benefit },

  ];

  return { bar, table, doughnut };
};

const getTotalDemandMW = (topologyGroups) => {
  let total = 0;

  topologyGroups.forEach(group => {
    total += getDemandMW(group);
  });

  return total;
};


const getNWADemandMW = (group, energyType) => {
  let total = 0;

  if (!group || typeof group.forEach !== "function") return 0;

  group.forEach((node, key) => {
    // 🔑 key 자체가 에너지원 이름
    if (key !== energyType) return;

    node.property?.forEach(prop => {
      prop.values?.forEach(v => {
        if (v.name === "여유용량") {
          total += Number(v.data) || 0;
        }
      });
    });
  });

  return total;
};

const calcCarbon = ({ capacityMW, HOURS_PER_YEAR, factor }) => {
  const mw = Number(capacityMW) || 0;
  const f = Number(factor) || 0;
  return mw * HOURS_PER_YEAR * f;
};


const getDemandMW = (group) => {
  const demand =
    group.get("수요지역") ||
    group.get("수요지역-A") ||
    group.get("수요지역-B");

  if (!demand) return 0;

  const demandMW = Number(
    demand.property?.[0]?.values?.find(v => v.name.includes("수요"))?.data
  );

  return isNaN(demandMW) ? 0 : demandMW;
};





// ==============================
// 📊 Chart 생성
// ==============================
const destroyCharts = () => {
  barChartInstances.forEach(c => c?.destroy())
  doughnutChartInstances.forEach(c => c?.destroy())

  barChartInstances = []
  doughnutChartInstances = []
}

const createCharts = async () => {
  await nextTick()
  destroyCharts()
  createCarbonView()

  const safeNum = (val) => {
    const num = Number(val)
    return isNaN(num) || !isFinite(num) ? 0 : num
  }

  const topologyCount = topologyList.value.length
  if (topologyCount === 0) return

  /* ===============================
   * 1️⃣ 테이블 생성 (기존 로직 유지)
   * =============================== */
  const categories = [
    "765kV", "345kV", "154kV", "22.9kV",
    "배전망 합계",
    "태양광", "풍력", "해상풍력", "ESS", "EV", "EVC", "DR", "VPP",
    "NWAs 합계",
    "편익비용",
  ]

  const table = categories.map(cat => {
    const row = { category: cat }
    for (let i = 1; i <= topologyCount; i++) row[`list${i}`] = "-"
    return row
  })

  for (let i = 0; i < topologyCount; i++) {
    const group = map_topologyList.value[i]
    if (!group) continue

    const nwasNodes = Array.from(group.entries())
      .filter(([_k, v]) => v?.id === 7)
      .map(([key, val]) => ({ key, ...val }))

    const { table: singleTable } = calcCostData(group, nwasNodes)

    singleTable.forEach(({ category, value }) => {
      const target = table.find(t => t.category === category)
      if (target) target[`list${i + 1}`] = value
    })

    const getSum = (keys) =>
      keys.map(k => {
        const raw = table.find(t => t.category === k)?.[`list${i + 1}`] || "0"
        return safeNum(typeof raw === "string" ? raw.replace(/,/g, "") : raw)
      }).reduce((a, b) => a + b, 0)

    const sumTransmission = getSum(["765kV", "345kV", "154kV", "22.9kV"])
    const sumNWAs = getSum(["태양광", "풍력", "해상풍력", "ESS", "EV", "EVC", "DR", "VPP"])

    table.find(t => t.category === "배전망 합계")[`list${i + 1}`] =
      sumTransmission.toLocaleString()
    table.find(t => t.category === "NWAs 합계")[`list${i + 1}`] =
      sumNWAs.toLocaleString()
    table.find(t => t.category === "편익비용")[`list${i + 1}`] =
      (sumTransmission - sumNWAs).toLocaleString()
  }

  tableItems.value = table

  /* ===============================
   * 2️⃣ Topology별 Bar / Doughnut 차트 생성
   * =============================== */

  barCharts.value.forEach((barCanvas, idx) => {
    const group = map_topologyList.value[idx]
    if (!group) return

    const nwasNodes = Array.from(group.entries())
      .filter(([_k, v]) => v?.id === 7)
      .map(([key, val]) => ({ key, ...val }))

    const { bar } = calcCostData(group, nwasNodes)

    const chart = new Chart(barCanvas.getContext("2d"), {
      type: "bar",
      data: bar,
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: { stacked: true, grid: { display: false } },
          y: {
            stacked: true,
            beginAtZero: true,
            ticks: {
              callback: v => `${(v / 1_000_000).toLocaleString()} 백만`
            }
          }
        },
        plugins: {
          legend: {
            position: "bottom",
            labels: { usePointStyle: true, boxWidth: 10, padding: 15 }
          },
          tooltip: {
            callbacks: {
              label: ctx =>
                `${Math.round(ctx.parsed.y).toLocaleString("ko-KR")} 원`
            }
          },
          datalabels: {
            anchor: "center",
            align: "center",
            color: "#000",
            font: { weight: "bold" },
            formatter: v =>
              v > 0 ? `${Math.round(v / 1_000_000).toLocaleString()} 백만` : ""
          }
        }
      }
    })

    barChartInstances.push(chart)
  })

  doughnutCharts.value.forEach((canvas, idx) => {
    const group = map_topologyList.value[idx]
    if (!group) return

    const nwasNodes = Array.from(group.entries())
      .filter(([_k, v]) => v?.id === 7)
      .map(([key, val]) => ({ key, ...val }))

    const { bar } = calcCostData(group, nwasNodes)

    // ============================
    // 🔑 송배전망 / NWAs 합계 계산
    // ============================
    const transSum = bar.datasets
      .filter(d => ["765kV", "345kV", "154kV", "22.9kV"].includes(d.label))
      .reduce((s, d) => s + (d.data[0] || 0), 0)

    const nwasSum = bar.datasets
      .filter(d => !["765kV", "345kV", "154kV", "22.9kV", "B/C"].includes(d.label))
      .reduce((s, d) => s + (d.data[1] || 0), 0)

    const totalSum = transSum + nwasSum

    // ============================
    // ✅ txt 파일과 동일한 doughnut data
    // ============================
    const doughnutData = {
      labels: ["배전망", "NWAs"],
      datasets: [
        {
          data: [transSum, nwasSum],
          backgroundColor: ["#6A5DFF", "#FF6B6B"],
          borderWidth: 0,
        },
      ],
    }

    // ============================
    // ⭐ 중앙 텍스트 플러그인
    // ============================
    const centerTextPlugin = {
      id: "centerText",
      beforeDraw(chart) {
        const { ctx, chartArea } = chart
        if (!chartArea) return

        const { left, right, top, bottom } = chartArea
        const centerX = (left + right) / 2
        const centerY = (top + bottom) / 2

        const total = chart.data.datasets[0].data
          .reduce((a, b) => a + b, 0)

        ctx.save()
        ctx.textAlign = "center"
        ctx.textBaseline = "middle"

        // 🔹 숫자
        ctx.font = "bold 20px Pretendard"
        ctx.fillStyle = "#000"
        ctx.fillText(
          Math.round(total / 1_000_000).toLocaleString("ko-KR"),
          centerX,
          centerY
        )

        // 🔹 설명 텍스트 (아래로 살짝)
        ctx.font = "16px Pretendard"
        ctx.fillText(
          "총 건설비용 (백만)",
          centerX,
          centerY + 26
        )

        ctx.restore()
      },
    }

    // ============================
    // ✅ Chart 생성 (txt 디자인 1:1)
    // ============================
    const chart = new Chart(canvas.getContext("2d"), {
      type: "doughnut",
      data: doughnutData,
      options: {
        responsive: true,
        maintainAspectRatio: false,
        cutout: "70%",
        plugins: {
          legend: {
            position: "bottom",
            labels: {
              usePointStyle: true,
              boxWidth: 10,
              padding: 20,
              generateLabels: (chart) => {
                const data = chart.data.datasets[0].data
                const labels = chart.data.labels
                const total = data.reduce((a, b) => a + b, 0)

                return labels.map((label, i) => {
                  const val = data[i]
                  const percent =
                    total > 0 ? ((val / total) * 100).toFixed(1) : 0

                  return {
                    text: `${label} : ${Math.round(
                      val / 1_000_000
                    ).toLocaleString("ko-KR")}백만 (${percent}%)`,
                    fillStyle: chart.data.datasets[0].backgroundColor[i],
                    hidden: false,
                    index: i,
                  }
                })
              },
            },
          },

          // 🔥 txt 기준: 도넛 내부 datalabels 사용 안 함
          datalabels: {
            display: false,
          },

          tooltip: {
            callbacks: {
              label: (ctx) => {
                const val = ctx.raw
                const percent =
                  totalSum > 0 ? ((val / totalSum) * 100).toFixed(1) : 0

                return `${ctx.label}: ${Math.round(
                  val / 1_000_000
                ).toLocaleString("ko-KR")}백만 (${percent}%)`
              },
            },
          },
        },
      },
      plugins: [centerTextPlugin],
    })

    doughnutChartInstances.push(chart)
  })
}




// 탄소배출량 계산
const GENERATION_TYPES = new Set([
  "석탄화력",
  "원전",
  "소수력",
  "가스복합"
]);


const extractEnergyTypesFromTopology = (group) => {
  const types = new Set();
  if (!group || typeof group.forEach !== "function") return types;

  group.forEach((_node, key) => {
    // 🔑 key 자체가 이미 정규화된 에너지원 이름
    if (CARBON_FACTOR[key]) {
      types.add(key);
    }
  });

  return types;
};


const calcCarbonTableByTopology = (group, allTopologyGroups) => {
  const HOURS_PER_YEAR = 8760;

  const activeTypes = extractEnergyTypesFromTopology(group);

  const categories = [
    "석탄화력", "원전", "소수력", "가스복합",
    "태양광", "풍력", "해상풍력",
    "ESS", "EV", "EVC", "DR", "VPP"
  ];

  const result = {};

  categories.forEach(cat => {
    if (!activeTypes.has(cat)) {
      result[cat] = 0;
      return;
    }

    // ✅ 여기서 capacityMW 결정
    const capacityMW = GENERATION_TYPES.has(cat)
      ? getTotalDemandMW(allTopologyGroups)   // 발전소
      : getNWADemandMW(group, cat);            // NWA

    result[cat] = calcCarbon({
      capacityMW,
      HOURS_PER_YEAR,
      factor: CARBON_FACTOR[cat]
    });
  });

  return result;
};

const buildCarbonTable = () => {
  const categories = [
    "석탄화력", "원전", "소수력", "가스복합",
    "태양광", "풍력", "해상풍력",
    "ESS", "EV", "EVC", "DR", "VPP"
  ];

  return categories.map(cat => {
    const row = { category: cat };
    for (let i = 1; i <= topologyList.value.length; i++) {
      row[`list${i}`] = "-";
    }
    return row;
  });
};

const createCarbonView = async () => {
  await nextTick();

  if (!topologyList.value.length) return;

  // =========================
  // 1️⃣ 테이블 생성
  // =========================
  const table = buildCarbonTable();

  for (let i = 0; i < topologyList.value.length; i++) {
    const group = map_topologyList.value[i];
    if (!group) continue;

    const carbonMap = calcCarbonTableByTopology(group, map_topologyList.value);

    table.forEach(row => {
      const value = carbonMap[row.category];
      row[`list${i + 1}`] =
        value > 0
          ? Math.round(value).toLocaleString("ko-KR")
          : "-";
    });
  }

  // =========================
  // 2️⃣ 선택 Topology 차트
  // =========================


  const carbonMap =
    calcCarbonTableByTopology(selectedTopologyIndexes, map_topologyList.value);

  drawCarbonCharts(carbonMap);
};

const safeNumber = (v) => {
  const n = Number(v);
  return isNaN(n) ? 0 : n;
};

const drawCarbonCharts = (carbonMap) => {
  if (!carbonMap) return;

  // ============================
  // 0️⃣ 기존 차트 제거
  // ============================
  if (carbonBarChartInstance) {
    carbonBarChartInstance.destroy();
    carbonBarChartInstance = null;
  }

  if (carbonDoughnutChartInstance) {
    carbonDoughnutChartInstance.destroy();
    carbonDoughnutChartInstance = null;
  }

  // ============================
  // 1️⃣ Bar Chart 데이터
  // ============================

  const transmissionSum =
    safeNumber(carbonMap["석탄화력"]) +
    safeNumber(carbonMap["원전"]) +
    safeNumber(carbonMap["소수력"]) +
    safeNumber(carbonMap["가스복합"]);

  const nwasSum =
    safeNumber(carbonMap["태양광"]) +
    safeNumber(carbonMap["풍력"]) +
    safeNumber(carbonMap["해상풍력"]) +
    safeNumber(carbonMap["ESS"]) +
    safeNumber(carbonMap["EV"]) +
    safeNumber(carbonMap["EVC"]) +
    safeNumber(carbonMap["DR"]) +
    safeNumber(carbonMap["VPP"]);

  const barData = {
    labels: ["배전망", "NWAs"],
    datasets: [
      // ===== 배전망 =====
      {
        label: "석탄화력",
        data: [safeNumber(carbonMap["석탄화력"]), 0],
        backgroundColor: "#2563EB",
        stack: "total"
      },
      {
        label: "원전",
        data: [safeNumber(carbonMap["원전"]), 0],
        backgroundColor: "#3B82F6",
        stack: "total"
      },
      {
        label: "소수력",
        data: [safeNumber(carbonMap["소수력"]), 0],
        backgroundColor: "#60A5FA",
        stack: "total"
      },
      {
        label: "가스복합",
        data: [safeNumber(carbonMap["가스복합"]), 0],
        backgroundColor: "#93C5FD",
        stack: "total"
      },

      // ===== NWAs =====
      {
        label: "태양광",
        data: [0, safeNumber(carbonMap["태양광"])],
        backgroundColor: "#FBBF24",
        stack: "total"
      },
      {
        label: "풍력",
        data: [0, safeNumber(carbonMap["풍력"])],
        backgroundColor: "#34D399",
        stack: "total"
      },
      {
        label: "해상풍력",
        data: [0, safeNumber(carbonMap["해상풍력"])],
        backgroundColor: "#22C55E",
        stack: "total"
      },
      {
        label: "ESS",
        data: [0, safeNumber(carbonMap["ESS"])],
        backgroundColor: "#A78BFA",
        stack: "total"
      },
      {
        label: "EV",
        data: [0, safeNumber(carbonMap["EV"])],
        backgroundColor: "#818CF8",
        stack: "total"
      },
      {
        label: "EVC",
        data: [0, safeNumber(carbonMap["EVC"])],
        backgroundColor: "#38BDF8",
        stack: "total"
      }
    ]
  };


  // ============================
  // 2️⃣ Doughnut Chart 데이터
  // ============================

  const doughnutData = {
    labels: ["송배전망", "NWAs"],
    datasets: [{
      data: [transmissionSum, nwasSum],
      backgroundColor: ["#6A5DFF", "#FF6B6B"],
      borderWidth: 0
    }]
  };

  // ============================
  // 3️⃣ Bar Chart 생성
  // ============================
  if (carbonBarChart.value) {
    carbonBarChartInstance = new Chart(
      carbonBarChart.value.getContext("2d"),
      {
        type: "bar",
        data: barData,
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            datalabels: {
              // 🔥 막대(배전망, NWAs)마다 딱 한 번만 표시
              display: (ctx) => {
                const v = ctx.dataset.data[ctx.dataIndex];
                return v && v > 0;   // 값 있는 stack만 표시
              },

              formatter: (value) =>
                `${Math.round(value).toLocaleString()} kgCO₂`,

              color: "#111827",
              font: {
                weight: "bold",
                size: 14
              },
              anchor: "center",
              align: "center"
            },

            legend: {
              position: "bottom",
              labels: {
                usePointStyle: true,
                pointStyle: "circle"
              }
            },

            tooltip: {
              callbacks: {
                label: (ctx) => {
                  const v = ctx.parsed.y;
                  if (!v) return null;
                  return `${ctx.dataset.label} : ${Math.round(v).toLocaleString()} kgCO₂`;
                }
              }
            }
          },
          scales: {
            x: {
              stacked: true,
              grid: { display: false },

              categoryPercentage: 0.5, // 🔥 핵심
              barPercentage: 0.6       // 🔥 핵심
            },
            y: {
              stacked: true,
              beginAtZero: true,
              title: {
                display: true,
                text: "kgCO₂"
              },
              ticks: {
                callback: (v) => v.toLocaleString()
              }
            }
          }
        }
      }
    );
  }


  const carbonCenterTextPlugin = {
    id: "carbonCenterText",
    beforeDraw(chart) {
      const { width, height, ctx } = chart;
      const total = chart.data.datasets[0].data.reduce((a, b) => a + b, 0);

      ctx.save();
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";

      ctx.font = "bold 28px Pretendard";
      ctx.fillStyle = "#111827";
      ctx.fillText(
        total.toLocaleString(),
        width / 2,
        height / 2 - 6
      );

      ctx.font = "14px Pretendard";
      ctx.fillStyle = "#6B7280";
      ctx.fillText(
        "총 탄소배출량 (kgCO₂)",
        width / 2,
        height / 2 + 18
      );
      ctx.restore();
    }
  };

  // ============================
  // 4️⃣ Doughnut Chart 생성
  // ============================
  if (carbonDoughnutChart.value) {
    carbonDoughnutChartInstance = new Chart(
      carbonDoughnutChart.value.getContext("2d"),
      {
        type: "doughnut",
        data: doughnutData,
        options: {
          responsive: true,
          maintainAspectRatio: false,
          cutout: "70%",
          plugins: {
            datalabels: {
              display: (ctx) => {
                const value = ctx.dataset.data[ctx.dataIndex];
                return value && value > 0;
              },
              formatter: (value) => Math.round(value).toLocaleString() + ' kgCo2', // 🔥 소수점 제거
              color: "#ffffff",          // 🔥 흰색
              font: {
                weight: "bold",          // 🔥 두껍게
                size: 14                // 🔥 크게
              },
              anchor: "center",
              align: "center",
              clamp: true
            },
            legend: {
              position: "bottom",
              labels: {
                usePointStyle: true,   // 🔵 동그라미
                pointStyle: "circle",
                padding: 20,
              }
            },
            tooltip: {
              callbacks: {
                label: (ctx) =>

                  `${ctx.label} : ${Math.round(ctx.raw).toLocaleString()} kgCO₂`
              }
            }
          }
        },
        plugins: [carbonCenterTextPlugin] // ⭐ 중앙 텍스트
      }
    );
  }
};



const exportAllToPDF = () => {
  // 현재 날짜/시간 포맷 생성
  const now = new Date();
  const yyyy = now.getFullYear();
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const dd = String(now.getDate()).padStart(2, "0");
  const hh = String(now.getHours()).padStart(2, "0");
  const mi = String(now.getMinutes()).padStart(2, "0");

  const filename = `report_${yyyy}${mm}${dd}_${hh}${mi}.pdf`;

  // public 폴더에 있는 PDF 다운로드
  const link = document.createElement("a");
  link.href = "/pdf/report.pdf";   // public/report.pdf
  link.download = filename;

  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

onMounted(() => createCharts(),);


watch([selectedTopologyIndexes, topologyList], () => {
  createCharts();
}, { deep: true });


</script>




